-- American Corner PostgreSQL schema v1. Generated from the verified SQLite schema, reviewed before production use.
-- No DROP/TRUNCATE. Foreign keys are deferrable only for the controlled import transaction.
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS announcements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,category TEXT NOT NULL,audience TEXT NOT NULL,target TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',author_id BIGINT NOT NULL,year_id BIGINT,expires_at TEXT DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS archived_login_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT,email TEXT,ip TEXT,success BIGINT,created_at TEXT NOT NULL,archived_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id BIGINT,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id BIGINT,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS course_enrollments(course_id BIGINT NOT NULL,user_id BIGINT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(course_id,user_id));
CREATE TABLE IF NOT EXISTS courses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,code TEXT NOT NULL,level TEXT NOT NULL,track TEXT DEFAULT '',semester BIGINT NOT NULL,year_id BIGINT NOT NULL,teacher_id BIGINT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL,author TEXT DEFAULT '',document_year TEXT DEFAULT '',level TEXT DEFAULT '',audience TEXT NOT NULL,target TEXT DEFAULT '',filename TEXT NOT NULL,storage_name TEXT UNIQUE NOT NULL,mime TEXT NOT NULL,size BIGINT NOT NULL,uploaded_by BIGINT NOT NULL,created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'published');
CREATE TABLE IF NOT EXISTS events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,description TEXT DEFAULT '',kind TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT DEFAULT '',place TEXT DEFAULT '',audience TEXT NOT NULL,target TEXT DEFAULT '',owner_id BIGINT NOT NULL,year_id BIGINT,created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'published');
CREATE TABLE IF NOT EXISTS group_members(group_id BIGINT NOT NULL,user_id BIGINT NOT NULL,PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS groups(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,level TEXT DEFAULT '',track TEXT DEFAULT '',year_id BIGINT,kind TEXT NOT NULL DEFAULT 'academic',created_by BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS levels(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT UNIQUE NOT NULL,cycle TEXT NOT NULL,sort BIGINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS login_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT,email TEXT,ip TEXT,success BIGINT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_blocks(user_id BIGINT PRIMARY KEY,disabled BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS message_reports(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,message_id BIGINT NOT NULL,reporter_id BIGINT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL,reviewed_by BIGINT,reviewed_at TEXT,UNIQUE(message_id,reporter_id));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,link TEXT DEFAULT '',read_at TEXT,created_at TEXT NOT NULL, entity_type TEXT, entity_id BIGINT, received_at TEXT);
CREATE TABLE IF NOT EXISTS private_messages(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sender_id BIGINT NOT NULL,recipient_id BIGINT NOT NULL,body TEXT NOT NULL,day_key TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_deliveries(notification_id BIGINT NOT NULL,subscription_id BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts BIGINT NOT NULL DEFAULT 0,next_attempt_at TEXT NOT NULL,sent_at TEXT,last_error TEXT,PRIMARY KEY(notification_id,subscription_id));
CREATE TABLE IF NOT EXISTS push_preferences(user_id BIGINT PRIMARY KEY,enabled BIGINT NOT NULL DEFAULT 1,publications_enabled BIGINT NOT NULL DEFAULT 1,results_enabled BIGINT NOT NULL DEFAULT 1,other_enabled BIGINT NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,last_test_at TEXT);
CREATE TABLE IF NOT EXISTS push_subscriptions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,session_hash TEXT NOT NULL,endpoint TEXT UNIQUE NOT NULL,p256dh TEXT NOT NULL,auth TEXT NOT NULL,created_at TEXT NOT NULL,last_success_at TEXT,last_error TEXT);
CREATE TABLE IF NOT EXISTS request_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,status TEXT NOT NULL,note TEXT DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tracking TEXT UNIQUE NOT NULL,owner_id BIGINT NOT NULL,kind TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'received',assignee_id BIGINT,response TEXT DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,closed_at TEXT);
CREATE TABLE IF NOT EXISTS research(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,owner_id BIGINT NOT NULL,supervisor_id BIGINT,title TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Sujet proposé',milestone TEXT NOT NULL DEFAULT 'Choix du sujet',notes TEXT DEFAULT '',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reset_tokens(token_hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL,expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE IF NOT EXISTS result_views(result_id BIGINT NOT NULL,student_id BIGINT NOT NULL,first_viewed_at TEXT NOT NULL,last_viewed_at TEXT NOT NULL,view_count BIGINT NOT NULL DEFAULT 1,PRIMARY KEY(result_id,student_id));
CREATE TABLE IF NOT EXISTS results(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,course_id BIGINT NOT NULL,student_id BIGINT NOT NULL,score DOUBLE PRECISION NOT NULL,status TEXT NOT NULL DEFAULT 'draft',entered_by BIGINT NOT NULL,validated_by BIGINT,published_at TEXT,updated_at TEXT NOT NULL,UNIQUE(course_id,student_id));
CREATE TABLE IF NOT EXISTS roles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT UNIQUE NOT NULL,permissions TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', scope_type TEXT NOT NULL DEFAULT '', scope_value TEXT NOT NULL DEFAULT '', suspended BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL,csrf TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS share_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,entity_type TEXT NOT NULL,entity_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,action TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS share_recipients(entity_type TEXT NOT NULL,entity_id BIGINT NOT NULL,user_id BIGINT NOT NULL,notified_at TEXT,received_at TEXT,first_viewed_at TEXT,last_viewed_at TEXT,view_count BIGINT NOT NULL DEFAULT 0,ack_at TEXT,reminded_at TEXT,download_count BIGINT NOT NULL DEFAULT 0, revoked_at TEXT,PRIMARY KEY(entity_type,entity_id,user_id));
CREATE TABLE IF NOT EXISTS share_targets(entity_type TEXT NOT NULL,entity_id BIGINT NOT NULL,targets_json TEXT NOT NULL,requires_ack BIGINT NOT NULL DEFAULT 0,created_at TEXT NOT NULL,PRIMARY KEY(entity_type,entity_id));
CREATE TABLE IF NOT EXISTS technical_alerts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL,severity TEXT NOT NULL,title TEXT NOT NULL,impact TEXT NOT NULL,recommendation TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tracks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS user_display(user_id BIGINT PRIMARY KEY,font_px BIGINT);
CREATE TABLE IF NOT EXISTS user_roles(user_id BIGINT NOT NULL,role_id BIGINT NOT NULL,scope TEXT DEFAULT '', expires_at TEXT,PRIMARY KEY(user_id,role_id,scope));
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT DEFAULT '',identifier TEXT NOT NULL,password TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',level TEXT DEFAULT '',track TEXT DEFAULT '',year_id BIGINT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS video_overrides(user_id BIGINT PRIMARY KEY,limit_per_day BIGINT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS video_posts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,author_id BIGINT NOT NULL,title TEXT NOT NULL,storage_name TEXT UNIQUE NOT NULL,mime TEXT NOT NULL,size BIGINT NOT NULL,day_key TEXT NOT NULL,audience TEXT NOT NULL,target TEXT NOT NULL DEFAULT '',hidden BIGINT NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS years(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,label TEXT UNIQUE NOT NULL,active BIGINT NOT NULL DEFAULT 0,archived BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS file_blobs(storage_name TEXT PRIMARY KEY, data BYTEA NOT NULL, mime TEXT NOT NULL, size BIGINT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_file_blobs_size ON file_blobs(size);
